customFunctions:
// XToys HR + Paw — Production v1.9 — FORCE mode
// FORCE starts when remaining time <= forceLeadMinutes (slider).
// Probability controlled by forceProbability (0-100%).
// Debug console.logs kept for testing.
// Check is done both on timer and on every HR event (HR path is the reliable one).

var OUT_CHANNEL = 'generic-1-a';

function controlNumber(name, fallback, min, max) {
    var value;
    try { value = getVariable(name); } catch (e) { return fallback; }
    if (value === null || value === undefined || value === '') return fallback;
    var n = Number(value);
    if (!isFinite(n)) return fallback;
    return Math.max(min, Math.min(max, n));
}
function readHrCurve() {
    var low = controlNumber('hrLow', 60, 40, 100);
    var high = controlNumber('hrHigh', 130, 100, 160);
    var atLow = controlNumber('intLowHR', 70, 0, 100);
    var atHigh = controlNumber('intHighHR', 15, 0, 100);
    if (high <= low) { low = 60; high = 130; }
    if (atHigh > atLow) atHigh = atLow;
    return {low:low, high:high, atLow:atLow, atHigh:atHigh};
}

var PAW_START_DELAY_MIN = 10;
var scriptStartedAt = Date.now();
var sessionMinutes = controlNumber('sessionDuration', 30, 1, 180);
var sessionDeadline = scriptStartedAt + sessionMinutes * 60000;

var sessionEnded = false;
var forceMode = false;
var forceDecisionMade = false;
var forceWillTrigger = false;
var forceRampUntil = 0;
var pawButtonHeld = false;

function readSettings() {
    var v = {
        pawDownRamp: controlNumber('pawDownRamp', 1, 0, 5),
        pawHoldTime: controlNumber('pawHoldTime', 8, 1, 30),
        pawRearmTime: controlNumber('pawRearmTime', 30, 20, 120),
        emergencyHR: controlNumber('emergencyHR', 150, 120, 180),
        emergencyReleaseHR: controlNumber('emergencyReleaseHR', 115, 80, 130),
        emergencyReleaseDelay: controlNumber('emergencyReleaseDelay', 8, 0, 15),
        recoveryRamp: controlNumber('recoveryRamp', 12, 1, 30),
        watchdogTimeout: controlNumber('watchdogTimeout', 10, 3, 30),
        forceLeadMinutes: controlNumber('forceLeadMinutes', 10, 0, 60),
        forceProbability: controlNumber('forceProbability', 100, 0, 100)
    };
    if (v.emergencyReleaseHR >= v.emergencyHR)
        v.emergencyReleaseHR = v.emergencyHR - 1;
    var sequenceSeconds = v.pawHoldTime + v.recoveryRamp;
    if (v.pawRearmTime < sequenceSeconds)
        v.pawRearmTime = sequenceSeconds;
    return v;
}

var lastBpm = null, lastValidHrAt = 0;
var mode = 'WAIT_HR';
var phaseId = 0;
var lastPawAt = 0;
var lastPawRearmMs = 0;
var emergencyCheckRunning = false;

function output(percent, seconds) {
    if (sessionEnded || Date.now() >= sessionDeadline) {
        sessionEnded = true;
        percent = 0;
        seconds = 0;
    }
    var p = Math.max(0, Math.min(100, Math.round(percent)));
    callAction({"type":"updateComponent","action":"setVolume","channel":OUT_CHANNEL,
                "rampTime":String(seconds),"percentVolume":String(p)});
}
function hrTarget(bpm) {
    var c = readHrCurve();
    var t = Math.max(0, Math.min(1, (bpm - c.low)/(c.high - c.low)));
    return c.atLow + (c.atHigh - c.atLow)*t;
}
function getBpm(data) {
    var a = [];
    if (data) a = [data['trigger-result'],data['trigger'],data.bpm,data.value,data.heartRate,data.heartrate];
    for (var i=0; i<a.length; i++) {
        var v = a[i];
        if (v && typeof v === 'object') {
            if (v.bpm !== undefined) v=v.bpm;
            else if (v.value !== undefined) v=v.value;
            else if (v.heartRate !== undefined) v=v.heartRate;
        }
        var n = Number(v);
        if (isFinite(n) && n>0) return n;
    }
    return null;
}
function armClock() {
    callAction({"type":"updateScript","part":"timer","seconds":"1",
                "setVariable":null,"goToPage":null});
}
function endSession() {
    if (sessionEnded) return;
    sessionEnded = true;
    phaseId++;
    mode = 'SESSION_END';
    output(0, 0);
    console.log('SESSION_END');
}
function checkSession() {
    if (sessionEnded) return true;
    if (Date.now() >= sessionDeadline) {
        endSession();
        return true;
    }
    return false;
}
function decideForceProbability() {
    if (forceDecisionMade) return;
    forceDecisionMade = true;
    var prob = readSettings().forceProbability;
    forceWillTrigger = (Math.random() * 100) < prob;
    console.log('FORCE probability decision: ' + prob + '% → willTrigger=' + forceWillTrigger);
    setVariable('forceDebug', 'PROB_DECIDED_' + (forceWillTrigger ? 'YES' : 'NO'));
}
function enterForceMode() {
    if (forceMode || sessionEnded) return;
    var settings = readSettings();
    if (settings.forceLeadMinutes <= 0) return;

    var remainingMs = sessionDeadline - Date.now();
    var leadMs = settings.forceLeadMinutes * 60000;
    if (remainingMs > leadMs) return;

    decideForceProbability();
    if (!forceWillTrigger) return;

    console.log('FORCE ENTERING, remainingMs=' + remainingMs + ', lead=' + settings.forceLeadMinutes + 'min');
    phaseId++;
    forceMode = true;
    mode = 'FORCE';
    var rampSeconds = settings.recoveryRamp;
    forceRampUntil = Date.now() + rampSeconds * 1000;
    output(100, rampSeconds);
    setVariable('forceDebug', 'FORCE_ENTERED');
}
function enterEmergency() {
    if (forceMode) return;
    if (mode !== 'EMERGENCY') {
        phaseId++;
        mode = 'EMERGENCY';
    }
    output(0,0);
}
function enterLost() {
    if (forceMode) return;
    phaseId++;
    mode = 'HR_LOST';
    lastBpm = null;
    output(0,0);
}
function beginRamp(newMode) {
    if (checkSession()) return;
    if (forceMode) return;
    if (lastBpm === null) return;
    phaseId++;
    var mine = phaseId;
    mode = newMode;
    var rampSeconds = readSettings().recoveryRamp;
    output(hrTarget(lastBpm),rampSeconds);
    sleep(rampSeconds * 1000);
    if (checkSession() || phaseId !== mine || mode !== newMode) return;
    mode = 'NORMAL';
    if (lastBpm !== null) output(hrTarget(lastBpm),0);
}
function emergencyReleaseCheck() {
    if (checkSession()) return;
    if (forceMode) return;
    if (emergencyCheckRunning || mode !== 'EMERGENCY') return;
    emergencyCheckRunning = true;
    var waitMs = readSettings().emergencyReleaseDelay * 1000;
    sleep(waitMs);
    emergencyCheckRunning = false;
    if (checkSession() || mode !== 'EMERGENCY') return;
    if (lastBpm === null || lastBpm > readSettings().emergencyReleaseHR) return;
    if (Date.now() - lastValidHrAt >= readSettings().watchdogTimeout * 1000) {
        enterLost();
        return;
    }
    beginRamp('RECOVERY');
}
function onHeartRate(data) {
    if (checkSession()) return;
    enterForceMode();
    var bpm = getBpm(data);
    if (bpm === null) return;
    lastBpm = bpm;
    lastValidHrAt = Date.now();
    if (forceMode) return;
    var safety = readSettings();
    if (bpm >= safety.emergencyHR) {
        enterEmergency();
        return;
    }
    if (mode === 'EMERGENCY') {
        output(0,0);
        if (bpm <= safety.emergencyReleaseHR) emergencyReleaseCheck();
        return;
    }
    if (mode === 'WAIT_HR' || mode === 'HR_LOST') {
        beginRamp('STARTUP');
        return;
    }
    if (mode === 'STARTUP' || mode === 'RECOVERY' || mode === 'PAW') return;
    if (mode === 'NORMAL') output(hrTarget(bpm),0);
}
function onTimerElapsed(data) {
    if (checkSession()) return;
    armClock();
    enterForceMode();
    if (forceMode && mode === 'FORCE' && Date.now() >= forceRampUntil) output(100, 0);
    if (!lastValidHrAt) return;
    if (Date.now() - lastValidHrAt < readSettings().watchdogTimeout * 1000) return;
    if (mode !== 'HR_LOST' && !forceMode) enterLost();
}
function onPawDown(data) {
    if (checkSession()) return;
    var now = Date.now();
    if (pawButtonHeld) return;
    pawButtonHeld = true;
    var pawStartMinutes = controlNumber('pawStartDelay', PAW_START_DELAY_MIN, 0, 60);
    if (now - scriptStartedAt < pawStartMinutes * 60000) return;
    if (mode !== 'NORMAL' && mode !== 'FORCE') return;
    var pawSettings = readSettings();
    if (lastPawAt && now - lastPawAt < lastPawRearmMs) return;
    lastPawAt = now;
    lastPawRearmMs = pawSettings.pawRearmTime * 1000;
    phaseId++;
    var mine = phaseId;
    mode = 'PAW';
    output(0,pawSettings.pawDownRamp);
    sleep(pawSettings.pawHoldTime * 1000);
    if (checkSession() || phaseId !== mine || mode !== 'PAW') return;
    var targetPercent = forceMode ? 100 : (lastBpm === null ? 0 : hrTarget(lastBpm));
    if (!forceMode && lastBpm === null) { enterLost(); return; }
    var rampSeconds = pawSettings.recoveryRamp;
    output(targetPercent, rampSeconds);
    sleep(rampSeconds * 1000);
    if (checkSession() || phaseId !== mine || mode !== 'PAW') return;
    if (forceMode) {
        mode = 'FORCE';
        forceRampUntil = Date.now();
        output(100, 0);
    } else {
        mode = 'NORMAL';
        if (lastBpm !== null) output(hrTarget(lastBpm),0);
    }
}
function onPawUp(data) {
    pawButtonHeld = false;
}

registerTrigger({"type":"componentState","channel":"heart-rate-a","event":"any"},onHeartRate);
registerTrigger({"type":"componentState","channel":"part-button-a","state":"down"},onPawDown);
registerTrigger({"type":"componentState","channel":"part-button-a","state":"up"},onPawUp);
registerTrigger({"type":"scriptState","part":"timer","amount":"1"},onTimerElapsed);
output(0,0);
armClock();
console.log('Script started, session=' + sessionMinutes + ' min');

var STOP_VARIABLE = "stop";
var TICK_VARIABLE = "time-elapsed";
var TICK_MIN_MS = 250;

var CIVET_TRIGGER = {
  "type": "componentState",
  "channel": "part-pressure-a",
  "event": "any"
};

var DEFAULTS = {
  cooldownThreshold: 70,
  stimulationThreshold: 40,
  cooldownSec: 20,
  RampToggle: true,
  minSpeed: 15,
  maxSpeed: 80,
  rampPerSec: 1.5,
  AllowClimax: false,
  edgesTarget: 5,
  cumSpeed: 100
};

var PRESSURE_KEYS = ["trigger-result", "value", "pressure", "level", "percent"];

var state = "";
var speed = 0;
var rampSpeed = 0;
var lastSent = -1;
var lastTick = Date.now();
var stateSince = lastTick;
var edges = 0;
var resumeSpeed = DEFAULTS.minSpeed;
var pressure = NaN;
var pressureKey = null;
var published = {};
var debugCount = 0;
var sampleCount = 0;
var tickCount = 0;

function cfg(name) {
  var n = parseFloat(getVariable(name));
  return isNaN(n) ? DEFAULTS[name] : n;
}

function flag(name) {
  var v = getVariable(name);
  if (v === true || v === "true") return true;
  if (v === false || v === "false") return false;
  return DEFAULTS[name];
}

function isTrue(v) {
  return v === true || v === "true" || v === 1 || v === "1";
}

function publish(name, value) {
  if (published[name] !== value) {
    published[name] = value;
    setVariable(name, value);
  }
}

function extractPressure(data) {
  if (data === null || data === undefined) return NaN;
  if (typeof data === "number" || typeof data === "string") return parseFloat(data);
  if (pressureKey !== null && data[pressureKey] !== undefined) return parseFloat(data[pressureKey]);
  for (var i = 0; i < PRESSURE_KEYS.length; i++) {
    if (data[PRESSURE_KEYS[i]] !== undefined) {
      pressureKey = PRESSURE_KEYS[i];
      return parseFloat(data[pressureKey]);
    }
  }
  for (var k in data) {
    var n = parseFloat(data[k]);
    if (!isNaN(n)) {
      pressureKey = k;
      console.log("Pressure read from field: " + k);
      return n;
    }
  }
  return NaN;
}

function setSpeed(pct, force) {
  rampSpeed = Math.max(0, Math.min(100, pct));
  speed = Math.round(rampSpeed);
  if (force || speed !== lastSent) {
    lastSent = speed;
    callAction({
      "type": "updateComponent",
      "channel": "part-linear-actuator-a",
      "action": "setVolume",
      "rampTime": 0,
      "percentVolume": String(speed)
    });
  }
  publish("speed", speed);
}

function goTo(newState) {
  console.log("State: " + state + " -> " + newState);
  state = newState;
  stateSince = Date.now();
  publish("state", newState);
}

function emergencyStop() {
  setSpeed(0, true);
  if (state !== "STOPPED") goTo("STOPPED");
}

function startStimulation() {
  setSpeed(flag("RampToggle") ? resumeSpeed : cfg("maxSpeed"));
  goTo("STIMULATION");
}

function tick() {
  var now = Date.now();
  var dt = (now - lastTick) / 1000;
  lastTick = now;
  if (isNaN(pressure)) return;
  publish("pressure", Math.round(pressure));

  if (++sampleCount % 20 === 0) {
    console.log("pressure=" + Math.round(pressure) + " state=" + state + " speed=" + speed + " edges=" + edges);
  }

  if (state === "STOPPED") return;
  if (isTrue(getVariable(STOP_VARIABLE))) {
    emergencyStop();
    return;
  }

  if (state === "STIMULATION") {
    if (pressure >= cfg("cooldownThreshold")) {
      edges++;
      publish("deniedOrgasms", edges);
      console.log("Edge #" + edges);
      resumeSpeed = Math.max(cfg("minSpeed"), speed * 0.6);
      setSpeed(0);
      goTo("RECOVERY");
    } else if (flag("RampToggle")) {
      setSpeed(Math.min(cfg("maxSpeed"), rampSpeed + cfg("rampPerSec") * dt));
    } else {
      setSpeed(cfg("maxSpeed"));
    }
  } else if (state === "RECOVERY") {
    if (pressure <= cfg("stimulationThreshold")) goTo("COOLDOWN");
  } else if (state === "COOLDOWN") {
    if (pressure > cfg("stimulationThreshold")) {
      goTo("RECOVERY");
    } else if ((now - stateSince) / 1000 >= cfg("cooldownSec")) {
      if (flag("AllowClimax") && edges >= cfg("edgesTarget")) {
        setSpeed(cfg("cumSpeed"));
        goTo("CLIMAX");
      } else {
        startStimulation();
      }
    }
  } else if (state === "CLIMAX") {
    setSpeed(cfg("cumSpeed"));
  }
}

function onPressure(data) {
  try {
    var raw = extractPressure(data);
    if (debugCount < 5) {
      console.log("Civet data: " + JSON.stringify(data) + " -> pressure = " + raw);
      debugCount++;
    }
    if (isNaN(raw)) return;
    pressure = raw;
    tick();
  } catch (e) {
    console.log("Error: " + e);
  }
}

function onTick() {
  try {
    if (state === "STOPPED" || Date.now() - lastTick < TICK_MIN_MS) return;
    if (++tickCount === 1) console.log("Tick source OK: " + TICK_VARIABLE);
    tick();
  } catch (e) {
    console.log("Error: " + e);
  }
}

function onStopChange() {
  try {
    if (isTrue(getVariable(STOP_VARIABLE))) emergencyStop();
  } catch (e) {
    console.log("Error: " + e);
  }
}

publish("deniedOrgasms", 0);
resumeSpeed = cfg("minSpeed");
startStimulation();
registerTrigger(CIVET_TRIGGER, onPressure);
registerTrigger({"type": "variableChange", "variable": STOP_VARIABLE}, onStopChange);
registerTrigger({"type": "variableChange", "variable": TICK_VARIABLE}, onTick);
console.log("Edging ready.");
